use super::*;
#[derive(Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]struct Payload{policy:SignedPolicy,records:Vec<Revision>,acknowledged_hash:Option<String>}
#[derive(Debug,Deserialize)]#[serde(deny_unknown_fields)]pub struct ExportRequest{pub workspace_id:String,pub recipient:String,pub kind:String}
#[derive(Debug,Deserialize)]#[serde(deny_unknown_fields)]pub struct ImportRequest{pub packet:String,pub expected_owner:String}
#[derive(Debug,Serialize)]pub struct ExchangeResult{pub workspace_id:String,pub packet_hash:String,pub kind:String,pub duplicate:bool,pub explanation:String}
impl Store{
 fn margin_decode(&self,text:&str)->RefractResult<(sync_engine::secure::Header,Payload,String)>{let me=self.margin_identity_private()?;let(h,plain)=secure::open(&me,text)?;let payload:Payload=serde_json::from_str(&plain).map_err(err)?;payload.policy.validate()?;if h.workspace_id!=payload.policy.data.id||h.epoch!=payload.policy.data.epoch{return Err(invalid("Packet/policy binding mismatch"));}let role=payload.policy.role(&h.sender);if (h.kind=="invite"||h.kind=="policy")&&h.sender!=payload.policy.data.owner||h.kind=="sync"&&!["owner","editor"].contains(&role)||h.kind=="receipt"&&role=="removed"{return Err(invalid("Sender is not authorized for this transfer kind"));}if ["policy","receipt"].contains(&h.kind.as_str())&&!payload.records.is_empty(){return Err(invalid("Policy/receipt cannot carry edits"));}if h.kind!="policy"&&payload.policy.role(&me.contact.data.signing_key)=="removed"{return Err(invalid("Recipient is not selected by this policy"));}let hash=evidence_engine::sha256_hex(text.as_bytes());Ok((h,payload,hash))}
 pub fn margin_inspect(&self,text:&str)->RefractResult<serde_json::Value>{let(h,payload,hash)=self.margin_decode(text)?;let me=self.margin_contact()?.data.signing_key;let records=payload.records.iter().map(|r|(r.id.clone(),r.clone())).collect::<BTreeMap<_,_>>();if records.len()!=payload.records.len(){return Err(invalid("Duplicate revision IDs"));}validate_records(&records)?;Ok(serde_json::json!({"workspace_id":h.workspace_id,"name":payload.policy.data.name,"owner":payload.policy.data.owner,"sender":h.sender,"kind":h.kind,"epoch":h.epoch,"my_role":payload.policy.role(&me),"revision_count":records.len(),"packet_hash":hash,"entries":records.values().filter(|r|heads(&records,&r.entry_id).iter().any(|v|v.id==r.id)).collect::<Vec<_>>(),"members":payload.policy.data.members,"warning":"A valid signature identifies a device key, not a verified person. Verify the owner fingerprint independently before accepting a new workspace. Removed/deleted records can remain in collaborative history."}))}
 pub fn margin_export_packet(&self,q:&ExportRequest)->RefractResult<String>{
  let(p,doc,enabled,revision)=self.margin_load(&q.workspace_id)?;if !enabled{return Err(invalid("Manual exchange is paused; local edits remain saved"));}let me=self.margin_identity_private()?;let role=p.role(&me.contact.data.signing_key);if q.recipient==me.contact.data.signing_key||!["invite","sync","policy"].contains(&q.kind.as_str())||!["owner","editor"].contains(&role)||(q.kind!="sync"&&role!="owner"){return Err(invalid("Only owner invites/changes policy; editors may exchange shared state"));}
  let to=if q.kind=="policy"{let stored:Option<String>=self.conn.query_row("SELECT contact_json FROM margin_contacts WHERE workspace_id=?1 AND peer_key=?2",params![q.workspace_id,q.recipient],|r|r.get(0)).optional().map_err(err)?;if let Some(s)=stored{serde_json::from_str(&s).map_err(err)?}else{p.member(&q.recipient)?.contact.clone()}}else{p.member(&q.recipient)?.contact.clone()};
  let records=if q.kind=="policy"{vec![]}else{Self::margin_records(&doc)?.into_values().collect()};let payload=Payload{policy:p.clone(),records,acknowledged_hash:None};let packet=secure::seal(&me,&to,&q.workspace_id,p.data.epoch,&q.kind,&json(&payload)?)?;let hash=evidence_engine::sha256_hex(packet.as_bytes());let tx=self.conn.unchecked_transaction().map_err(err)?;tx.execute("INSERT INTO margin_transfers(hash,workspace_id,direction,kind,peer_key,local_revision,packet,created_ts) VALUES(?1,?2,'out',?3,?4,?5,?6,?7)",params![hash,q.workspace_id,q.kind,q.recipient,revision,packet,now()]).map_err(err)?;self.margin_log(&q.workspace_id,"export_prepared",&format!("{} packet {hash} for {}; delivery unconfirmed",q.kind,q.recipient))?;tx.commit().map_err(err)?;Ok(packet)
 }
 pub fn margin_import_packet(&self,q:&ImportRequest)->RefractResult<ExchangeResult>{
  let(h,payload,hash)=self.margin_decode(&q.packet)?;let id=&h.workspace_id;let me=self.margin_contact()?.data.signing_key;if q.expected_owner!=payload.policy.data.owner{return Err(invalid("Owner fingerprint confirmation does not match"));}let exists:i64=self.conn.query_row("SELECT COUNT(*) FROM margin_workspaces WHERE id=?1",params![id],|r|r.get(0)).map_err(err)?;let(mut doc,old_policy)=if exists>0{let(old,doc,enabled,_)=self.margin_load(id)?;if !enabled{return Err(invalid("Manual exchange is paused; enable it before importing"));}if old.data.owner!=payload.policy.data.owner||payload.policy.data.epoch<old.data.epoch||payload.policy.data.epoch==old.data.epoch&&old!=payload.policy{return Err(invalid("Stale, forked or unrelated owner policy"));}(doc,Some(old))}else{if h.kind!="invite"{return Err(invalid("New workspaces require an explicit owner invitation"));}(AnnotationDoc::new(),None)};
  let seen:i64=self.conn.query_row("SELECT COUNT(*) FROM margin_transfers WHERE hash=?1 AND direction='in'",params![hash],|r|r.get(0)).map_err(err)?;if seen>0{return Ok(ExchangeResult{workspace_id:id.clone(),packet_hash:hash,kind:h.kind,duplicate:true,explanation:"Already imported; no changes or fake delivery progress recorded".into()});}
  let mut records=Self::margin_records(&doc)?;let mut incoming=BTreeSet::new();for r in &payload.records{if !incoming.insert(&r.id){return Err(invalid("Duplicate incoming revision"));}if let Some(old)=records.get(&r.id){if old!=r{return Err(invalid("An immutable revision was changed"));}}else{records.insert(r.id.clone(),r.clone());}}
  validate_records(&records)?;for r in &payload.records{doc.upsert(&r.id,&json(r)?)?;}
  let tx=self.conn.unchecked_transaction().map_err(err)?;
  if old_policy.is_none(){tx.execute("INSERT INTO margin_workspaces(id,policy_json,state,created_ts,updated_ts) VALUES(?1,?2,?3,?4,?4)",params![id,json(&payload.policy)?,doc.export_state()?,now()]).map_err(err)?;}else{tx.execute("UPDATE margin_workspaces SET policy_json=?2 WHERE id=?1",params![id,json(&payload.policy)?]).map_err(err)?;}
  if h.kind=="receipt"{let ack=payload.acknowledged_hash.as_deref().ok_or_else(||invalid("Receipt missing packet hash"))?;let n=tx.execute("UPDATE margin_transfers SET acknowledged_ts=COALESCE(acknowledged_ts,?3) WHERE hash=?1 AND workspace_id=?2 AND direction='out' AND peer_key=?4",params![ack,id,now(),h.sender]).map_err(err)?;if n!=1{return Err(invalid("Receipt does not acknowledge a packet addressed to its signing device"));}}
  for m in &payload.policy.data.members{tx.execute("INSERT INTO margin_contacts(workspace_id,peer_key,contact_json) VALUES(?1,?2,?3) ON CONFLICT(workspace_id,peer_key) DO UPDATE SET contact_json=excluded.contact_json",params![id,m.contact.data.signing_key,json(&m.contact)?]).map_err(err)?;}
  tx.execute("INSERT INTO margin_transfers(hash,workspace_id,direction,kind,peer_key,local_revision,created_ts) VALUES(?1,?2,'in',?3,?4,0,?5)",params![hash,id,h.kind,h.sender,now()]).map_err(err)?;
  self.margin_persist(id,&mut doc,"authenticated_import",&format!("{} packet {hash}; verified exporter {}; epoch {}",h.kind,h.sender,h.epoch))?;tx.commit().map_err(err)?;
  Ok(ExchangeResult{workspace_id:id.clone(),packet_hash:hash,kind:h.kind,duplicate:false,explanation:if payload.policy.role(&me)=="removed"{"Owner policy removed this device. Previously received local copies remain; exchange is no longer authorized."}else{"Imported transactionally. Concurrent versions remain visible. New workspaces start with further exchange paused; no original document was imported."}.into()})
 }
 pub fn margin_receipt(&self,id:&str,hash:&str)->RefractResult<String>{let(p,_,enabled,_)=self.margin_load(id)?;if !enabled{return Err(invalid("Enable exchange before preparing a receipt"));}let me=self.margin_identity_private()?;if p.role(&me.contact.data.signing_key)=="removed"{return Err(invalid("Removed device cannot send receipts"));}let(peer,kind):(String,String)=self.conn.query_row("SELECT peer_key,kind FROM margin_transfers WHERE hash=?1 AND workspace_id=?2 AND direction='in'",params![hash,id],|r|Ok((r.get(0)?,r.get(1)?))).optional().map_err(err)?.ok_or_else(||invalid("Imported packet not found"))?;if kind=="receipt"{return Err(invalid("Receipts do not require receipts"));}let payload=Payload{policy:p.clone(),records:vec![],acknowledged_hash:Some(hash.into())};secure::seal(&me,&p.member(&peer)?.contact,id,p.data.epoch,"receipt",&json(&payload)?)}
 pub fn margin_transfers(&self,id:&str)->RefractResult<serde_json::Value>{self.margin_load(id)?;let mut stmt=self.conn.prepare("SELECT hash,direction,kind,peer_key,local_revision,created_ts,acknowledged_ts FROM margin_transfers WHERE workspace_id=?1 ORDER BY created_ts DESC,rowid DESC LIMIT 100").map_err(err)?;let rows=stmt.query_map(params![id],|r|Ok(serde_json::json!({"hash":r.get::<_,String>(0)?,"direction":r.get::<_,String>(1)?,"kind":r.get::<_,String>(2)?,"peer_key":r.get::<_,String>(3)?,"local_revision":r.get::<_,i64>(4)?,"created_ts":r.get::<_,i64>(5)?,"acknowledged_ts":r.get::<_,Option<i64>>(6)?}))).map_err(err)?.collect::<Result<Vec<_>,_>>().map_err(err)?;Ok(serde_json::json!(rows))}
 pub fn margin_retry(&self,id:&str,hash:&str)->RefractResult<String>{let(p,_,enabled,_)=self.margin_load(id)?;if !enabled{return Err(invalid("Exchange is paused"));}self.margin_writer(&p)?;let packet:String=self.conn.query_row("SELECT packet FROM margin_transfers WHERE workspace_id=?1 AND hash=?2 AND direction='out'",params![id,hash],|r|r.get(0)).optional().map_err(err)?.ok_or_else(||invalid("Outgoing packet not found"))?;let parsed:secure::Packet=serde_json::from_str(&packet).map_err(err)?;if parsed.header.epoch!=p.data.epoch{return Err(invalid("Old policy epoch: prepare a new transfer instead"));}Ok(packet)}
}
